#!/usr/bin/env python3
from pathlib import Path
import subprocess
import sys
import re

FILES = {
    "seed_recovery_v82.py": "\nimport json\nimport os\nimport subprocess\nimport sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nREPORT_FILE = Path(\"seed_recovery_report_v82.json\")\nLAST_GREEN_FILE = Path(\"seed_last_green_checkpoint_v82.json\")\nROLLBACK_NOTES = Path(\"seed_recovery_rollback_notes_v82.md\")\n\nEXCLUDE_NAME_PARTS = [\n    \"installer\",\n    \"backup_\",\n    \"_backup\",\n]\n\nCORE_RUNTIME_FILES = [\n    \"seed_cli.py\",\n    \"seed_commands.py\",\n    \"seed_local_chat_v701.py\",\n    \"seed_v85_gate.py\",\n    \"seed_v85_systems.py\",\n    \"seed_self_state_v85.py\",\n    \"seed_recovery_v82.py\",\n    \"seed_runtime_v83.py\",\n    \"seed_privacy_backup_v84.py\",\n    \"seed_release_candidate_v85.py\",\n    \"seed_v81_gate.py\",\n    \"seed_v75_gate.py\",\n    \"seed_v74_gate.py\",\n    \"seed_v731_gate.py\",\n]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef should_compile(path):\n    name = path.name.lower()\n    if any(part in name for part in EXCLUDE_NAME_PARTS):\n        return False\n    return True\n\ndef seed_py_files():\n    files = []\n    for f in CORE_RUNTIME_FILES:\n        p = Path(f)\n        if p.exists():\n            files.append(p)\n    for p in sorted(Path(\".\").glob(\"seed_*.py\")):\n        if p not in files and should_compile(p):\n            files.append(p)\n    return files\n\ndef compile_file(path, timeout=25):\n    try:\n        proc = subprocess.run([sys.executable, \"-m\", \"py_compile\", str(path)], capture_output=True, text=True, timeout=timeout)\n        return {\"file\": str(path), \"ok\": proc.returncode == 0, \"stderr\": proc.stderr[-2000:]}\n    except subprocess.TimeoutExpired:\n        return {\"file\": str(path), \"ok\": False, \"stderr\": \"compile timeout\"}\n    except Exception as e:\n        return {\"file\": str(path), \"ok\": False, \"stderr\": str(e)}\n\ndef compile_all():\n    checks = [compile_file(p) for p in seed_py_files()]\n    failed = [c for c in checks if not c[\"ok\"]]\n    return {\"ok\": len(failed) == 0, \"count\": len(checks), \"failed\": failed, \"checks\": checks}\n\ndef read_report(path):\n    p = Path(path)\n    if not p.exists():\n        return {}\n    try:\n        return json.loads(p.read_text(errors=\"ignore\"))\n    except Exception:\n        return {}\n\ndef recursion_guard():\n    warnings = []\n    patterns = [\n        (\"seed_self_state_v741.py\", \"seed_v75_gate\", \"v75 self-state should not call v75 gate\"),\n        (\"seed_self_state_v81.py\", \"seed_v81_gate\", \"v81 self-state should not call v81 gate\"),\n        (\"seed_self_state_v85.py\", \"seed_v85_gate\", \"v85 self-state should not call v85 gate\"),\n    ]\n    for filename, needle, message in patterns:\n        p = Path(filename)\n        if p.exists() and needle in p.read_text(errors=\"ignore\"):\n            warnings.append({\"file\": filename, \"warning\": message})\n    return {\"ok\": len(warnings) == 0, \"warnings\": warnings}\n\ndef dependency_check():\n    import shutil\n    deps = {name: shutil.which(name) for name in [\"ffmpeg\", \"say\", \"aider\", \"git\"]}\n    try:\n        import faster_whisper\n        deps[\"faster_whisper\"] = True\n    except Exception:\n        deps[\"faster_whisper\"] = False\n    # git is critical; ffmpeg/say/whisper are already checked by voice gate but not fatal here.\n    return {\"ok\": bool(deps.get(\"git\")), \"deps\": deps}\n\ndef storage_check():\n    try:\n        usage = os.statvfs(\".\")\n        free_gb = usage.f_bavail * usage.f_frsize / (1024**3)\n        total_gb = usage.f_blocks * usage.f_frsize / (1024**3)\n        return {\"ok\": free_gb > 3, \"free_gb\": round(free_gb, 2), \"total_gb\": round(total_gb, 2)}\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e)}\n\ndef mark_last_green(label=\"manual_green_checkpoint\"):\n    data = {\n        \"created_at\": now(),\n        \"version\": \"v85.1.0\",\n        \"label\": label,\n        \"cwd\": str(Path(\".\").resolve()),\n    }\n    try:\n        proc = subprocess.run([\"git\", \"rev-parse\", \"--short\", \"HEAD\"], capture_output=True, text=True, timeout=8)\n        if proc.returncode == 0:\n            data[\"git_head\"] = proc.stdout.strip()\n    except Exception:\n        pass\n    LAST_GREEN_FILE.write_text(json.dumps(data, indent=4))\n    return data\n\ndef recovery_summary():\n    compile_report = compile_all()\n    guard = recursion_guard()\n    deps = dependency_check()\n    storage = storage_check()\n    blockers = []\n    warnings = []\n\n    if not compile_report[\"ok\"]:\n        blockers.append(f\"{len(compile_report['failed'])} runtime Python compile failures\")\n    if not guard[\"ok\"]:\n        blockers.append(\"recursion guard warnings\")\n    if not deps[\"ok\"]:\n        blockers.append(\"missing critical dependency: git\")\n    if not storage[\"ok\"]:\n        warnings.append(\"low storage or storage check warning\")\n\n    data = {\n        \"created_at\": now(),\n        \"version\": \"v85.1.0\",\n        \"ok\": len(blockers) == 0,\n        \"blockers\": blockers,\n        \"warnings\": warnings,\n        \"compile\": {\"ok\": compile_report[\"ok\"], \"count\": compile_report[\"count\"], \"failed\": compile_report[\"failed\"][:10]},\n        \"recursion_guard\": guard,\n        \"dependencies\": deps,\n        \"storage\": storage,\n        \"last_green\": read_report(LAST_GREEN_FILE),\n        \"note\": \"v85.1 compiles runtime modules and excludes installer artifacts from recovery health.\",\n    }\n    REPORT_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef write_rollback_notes():\n    summary = recovery_summary()\n    lines = [\n        \"# Seed v85.1 Recovery Notes\",\n        \"\",\n        f\"Created: {now()}\",\n        \"\",\n        \"## Status\",\n        f\"OK: {summary.get('ok')}\",\n        f\"Blockers: {summary.get('blockers')}\",\n        f\"Warnings: {summary.get('warnings')}\",\n        \"\",\n        \"## Manual rollback strategy\",\n        \"1. Stop running Seed servers with Ctrl+C.\",\n        \"2. Use the latest `seed_backup_*_green` folder on Desktop.\",\n        \"3. Or use `git log --oneline` then `git reset --hard <green_commit>`.\",\n        \"4. Re-run gates after rollback.\",\n        \"\",\n        \"## Current failed runtime compiles\",\n    ]\n    for fail in summary.get(\"compile\", {}).get(\"failed\", []):\n        lines.append(f\"- {fail.get('file')}: {fail.get('stderr')[:400]}\")\n    ROLLBACK_NOTES.write_text(\"\\n\".join(lines))\n    return {\"ok\": True, \"file\": str(ROLLBACK_NOTES)}\n\ndef show_recovery():\n    print(\"\\n=== SEED v85.1 RECOVERY / SELF-REPAIR ===\")\n    data = recovery_summary()\n    print(f\"OK: {data['ok']}\")\n    print(f\"Blockers: {data['blockers']}\")\n    print(f\"Warnings: {data['warnings']}\")\n    print(f\"Compile: {data['compile']['ok']} ({data['compile']['count']} runtime files)\")\n    print(f\"Storage: {data['storage']}\")\n    print(f\"Deps: {data['dependencies']['deps']}\")\n    if data[\"compile\"][\"failed\"]:\n        print(\"\\nFailed runtime compiles:\")\n        for f in data[\"compile\"][\"failed\"]:\n            print(f\"- {f['file']}: {f['stderr'][:500]}\")\n    print(\"\\nUse: mark green checkpoint | recovery notes\")\n\nif __name__ == \"__main__\":\n    show_recovery()\n",
    "seed_v85_gate.py": "\nimport json\nimport subprocess\nimport sys\nimport time\nfrom datetime import datetime\nfrom pathlib import Path\n\nMODULES = [\n    \"seed_self_state_v85.py\",\n    \"seed_recovery_v82.py\",\n    \"seed_runtime_v83.py\",\n    \"seed_privacy_backup_v84.py\",\n    \"seed_release_candidate_v85.py\",\n    \"seed_v85_systems.py\",\n    \"seed_v85_gate.py\",\n    \"seed_v85_commands.py\",\n    \"seed_natural_intent_router_v85.py\",\n]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef compile_module(module):\n    proc = subprocess.run([sys.executable, \"-m\", \"py_compile\", module], capture_output=True, text=True, timeout=30)\n    return {\"module\": module, \"ok\": proc.returncode == 0, \"stderr\": proc.stderr[-1600:]}\n\ndef read_report(path):\n    p = Path(path)\n    if not p.exists():\n        return {}\n    try:\n        return json.loads(p.read_text(errors=\"ignore\"))\n    except Exception:\n        return {}\n\ndef report_is_recent_and_ready(path, max_age_seconds=3600):\n    p = Path(path)\n    if not p.exists():\n        return False, {\"reason\": \"missing report\"}\n    try:\n        age = time.time() - p.stat().st_mtime\n        data = read_report(path)\n        return (age <= max_age_seconds and data.get(\"ready\") is True), {\"age_seconds\": round(age, 1), \"ready\": data.get(\"ready\"), \"version\": data.get(\"version\")}\n    except Exception as e:\n        return False, {\"reason\": str(e)}\n\ndef run_lower_gate_fast(path, report_path, timeout=45):\n    # Prefer cached report. User often runs v81 gate separately and it is already green.\n    ready, meta = report_is_recent_and_ready(report_path)\n    if ready:\n        return {\"ok\": True, \"source\": \"cached_report\", **meta}\n\n    if not Path(path).exists():\n        return {\"ok\": False, \"error\": f\"{path} missing\", \"source\": \"missing\"}\n    try:\n        proc = subprocess.run([sys.executable, path], capture_output=True, text=True, timeout=timeout)\n        return {\n            \"ok\": proc.returncode == 0,\n            \"source\": \"subprocess\",\n            \"returncode\": proc.returncode,\n            \"stdout_tail\": proc.stdout[-3000:],\n            \"stderr_tail\": proc.stderr[-3000:],\n        }\n    except subprocess.TimeoutExpired:\n        # On timeout, check if report was written anyway.\n        ready, meta = report_is_recent_and_ready(report_path, max_age_seconds=7200)\n        if ready:\n            return {\"ok\": True, \"source\": \"cached_after_timeout\", **meta}\n        return {\"ok\": False, \"error\": f\"{path} timeout\", \"source\": \"timeout\"}\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e), \"source\": \"exception\"}\n\ndef run_v85_gate():\n    checks = [compile_module(m) for m in MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n    details = {}\n\n    try:\n        from seed_v85_systems import build_v85_state\n        state = build_v85_state()\n        systems_ok = state.get(\"ok\") is True and len(state.get(\"cards\", [])) >= 5\n        details[\"v85_state\"] = {\"ok\": state.get(\"ok\"), \"cards\": len(state.get(\"cards\", []))}\n    except Exception as e:\n        systems_ok = False\n        details[\"v85_state_error\"] = str(e)\n\n    v81 = run_lower_gate_fast(\"seed_v81_gate.py\", \"seed_v81_gate_report.json\", timeout=45)\n    v81_ok = v81.get(\"ok\") is True\n    details[\"v81\"] = v81\n\n    try:\n        from seed_self_state_v85 import build_self_state\n        s = build_self_state()\n        truth_ok = s.get(\"true_current_version\") == \"v85.0.0\" or s.get(\"true_current_version\") == \"v85.1.0\"\n        details[\"truth\"] = {\"current\": s.get(\"true_current_version\"), \"green_layers\": s.get(\"installed_layers_green\", [])}\n    except Exception as e:\n        truth_ok = False\n        details[\"truth_error\"] = str(e)\n\n    try:\n        from seed_runtime_v83 import install_seed_script\n        script = install_seed_script()\n        script_ok = script.get(\"ok\") is True and Path(\"seed\").exists()\n        details[\"runtime_script\"] = script\n    except Exception as e:\n        script_ok = False\n        details[\"runtime_script_error\"] = str(e)\n\n    report = {\n        \"created_at\": now(),\n        \"version\": \"v85.1.0\",\n        \"ready\": modules_ok and systems_ok and v81_ok and truth_ok and script_ok,\n        \"modules_ok\": modules_ok,\n        \"systems_ok\": systems_ok,\n        \"v81_ok\": v81_ok,\n        \"truth_ok\": truth_ok,\n        \"script_ok\": script_ok,\n        \"module_checks\": checks,\n        \"details\": details,\n        \"hotfix\": \"v85.1 uses recent cached v81 gate report to avoid nested gate timeout.\",\n    }\n    open(\"seed_v85_gate_report.json\", \"w\").write(json.dumps(report, indent=4))\n    return report\n\ndef show_v85_gate():\n    r = run_v85_gate()\n    print(\"\\n=== SEED v85.1 REAL V1 PREP GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"Systems OK: {r['systems_ok']}\")\n    print(f\"v81 OK: {r['v81_ok']}\")\n    print(f\"Truth OK: {r['truth_ok']}\")\n    print(f\"Script OK: {r['script_ok']}\")\n    print(f\"Details: {r['details']}\")\n\nif __name__ == \"__main__\":\n    show_v85_gate()\n",
    "seed_v85_systems.py": "\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\n\nSTATE_FILE = Path(\"seed_v85_systems_state.json\")\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef safe(title, summary, fn):\n    try:\n        data = fn()\n        return {\"title\": title, \"summary\": summary, \"status\": \"ok\" if data.get(\"ok\", True) else \"warning\", \"data\": data}\n    except Exception as e:\n        return {\"title\": title, \"summary\": summary, \"status\": \"error\", \"error\": str(e)}\n\ndef build_v85_state():\n    cards = [\n        safe(\"v82 Recovery\", \"Runtime compile checks, recursion guard, dependencies, rollback notes.\", lambda: __import__(\"seed_recovery_v82\", fromlist=[\"recovery_summary\"]).recovery_summary()),\n        safe(\"v83 One-Command Runtime\", \"Seed can start via ./seed or seed_start.sh.\", lambda: __import__(\"seed_runtime_v83\", fromlist=[\"runtime_status\"]).runtime_status()),\n        safe(\"v84 Backup/Privacy\", \"Backup, export memory, forget by keyword.\", lambda: __import__(\"seed_privacy_backup_v84\", fromlist=[\"privacy_status\"]).privacy_status()),\n        safe(\"v85 Release Candidate\", \"RC report and README generation.\", lambda: __import__(\"seed_release_candidate_v85\", fromlist=[\"release_candidate_summary\"]).release_candidate_summary()),\n        safe(\"Self-State Truth\", \"Current version override is v85.0.0/v85.1 gate hotfix.\", lambda: __import__(\"seed_self_state_v85\", fromlist=[\"build_self_state\"]).build_self_state()),\n    ]\n    data = {\"created_at\": now(), \"version\": \"v85.1.0\", \"ok\": all(c[\"status\"] != \"error\" for c in cards), \"cards\": cards}\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef show_v85_status():\n    data = build_v85_state()\n    print(\"\\n=== SEED v85.1 REAL V1 PREP STATUS ===\")\n    print(f\"OK: {data['ok']}\")\n    for c in data[\"cards\"]:\n        print(f\"- {c['title']}: {c['status']} \u2014 {c['summary']}\")\n\nif __name__ == \"__main__\":\n    show_v85_status()\n",
}

for path, text in FILES.items():
    Path(path).write_text(text.strip() + "\n")
    print("Wrote", path)

# Update config
p = Path("seed_config.py")
text = p.read_text(errors="ignore") if p.exists() else 'SEED_VERSION = "v85.1.0"\n'
text = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v85.1.0"', text, flags=re.M)
if "SEED_V851_GATE_TIMEOUT_HOTFIX" not in text:
    text += '\nSEED_V851_GATE_TIMEOUT_HOTFIX = True\n'
p.write_text(text)
print("Updated seed_config.py")

# Docs
p = Path("Seed_Core.md")
text = p.read_text(errors="ignore") if p.exists() else ""
if "Seed v85.1 — Gate Timeout + Recovery Health Hotfix" not in text:
    text += """
## Seed v85.1 — Gate Timeout + Recovery Health Hotfix

Fixes:
- v85 gate no longer fails when nested v81 subprocess times out.
- v85 gate uses recent cached `seed_v81_gate_report.json` when already green.
- v82 recovery compiles runtime modules and excludes installer artifacts.
"""
p.write_text(text)
print("Updated Seed_Core.md")

# Compile checks.
for m in ["seed_recovery_v82.py", "seed_v85_gate.py", "seed_v85_systems.py", "seed_commands.py", "seed_local_chat_v701.py"]:
    if Path(m).exists():
        proc = subprocess.run([sys.executable, "-m", "py_compile", m], capture_output=True, text=True, timeout=30)
        print("$ python -m py_compile", m)
        if proc.returncode == 0:
            print("OK")
        else:
            print(proc.stderr)
            sys.exit(proc.returncode)

print("\nSeed v85.1 gate timeout/recovery hotfix installed.")
